{"version":3,"file":"api.jsdbx","sources":["../../src/client/services/api.ts"],"sourcesContent":["const TABLE = 'x_snc_voltworksr_0_visit_request'
const BASE = `/api/now/table/${TABLE}`
const HEADERS = {
 Accept: 'application/json',
 'Content-Type': 'application/json',
 'X-UserToken': (window as any).g_ck,
}

export async function fetchRequests() {
 const params = new URLSearchParams({
 sysparm_display_value: 'all',
 sysparm_limit: '50',
 sysparm_order_by: 'sys_created_on',
 sysparm_order_dir: 'desc',
 })
 const res = await fetch(`${BASE}?${params}`, { headers: HEADERS })
 if (!res.ok) throw new Error(`Failed to fetch: ${res.status}`)
 const data = await res.json()
 return data.result || []
}

export async function fetchRequest(sysId: string) {
 const res = await fetch(`${BASE}/${sysId}?sysparm_display_value=all`, { headers: HEADERS })
 if (!res.ok) throw new Error(`Failed to fetch record: ${res.status}`)
 const data = await res.json()
 return data.result
}

export async function createRequest(fields: Record<string, string>) {
 const res = await fetch(`${BASE}?sysparm_display_value=all&sysparm_input_display_value=true`, {
 method: 'POST',
 headers: HEADERS,
 body: JSON.stringify(fields),
 })
 if (!res.ok) {
 const err = await res.json().catch(() => ({}))
 throw new Error(err.error?.message || `Create failed: ${res.status}`)
 }
 return (await res.json()).result
}

export async function searchUsers(query: string) {
 const params = new URLSearchParams({
 sysparm_display_value: 'all',
 sysparm_limit: '8',
 sysparm_query: `nameLIKE${query}^active=true`,
 sysparm_fields: 'sys_id,name,email',
 })
 const res = await fetch(`/api/now/table/sys_user?${params}`, { headers: HEADERS })
 if (!res.ok) return []
 const data = await res.json()
 return data.result || []
}
